import ExpoModulesCore
import HealthKit

public class ExpoHealthModule: Module {
  private let healthStore = HKHealthStore()
  private let stepType = HKQuantityType.quantityType(forIdentifier: .stepCount)!

  public func definition() -> ModuleDefinition {
    Name("ExpoHealth")

    Function("getAuthorizationStatus") {
      self.statusString(self.healthStore.authorizationStatus(for: self.stepType))
    }

    AsyncFunction("requestAuthorization") { () async throws -> String in
      guard HKHealthStore.isHealthDataAvailable() else {
        throw ExpoHealthError.unavailable
      }
      try await withCheckedThrowingContinuation { (continuation: CheckedContinuation<Void, Error>) in
        self.healthStore.requestAuthorization(toShare: [self.stepType], read: [self.stepType]) { _, error in
          if let error {
            continuation.resume(throwing: error)
          } else {
            continuation.resume()
          }
        }
      }
      return self.statusString(self.healthStore.authorizationStatus(for: self.stepType))
    }

    AsyncFunction("saveSteps") { (steps: Double) async throws -> Void in
      let sample = HKQuantitySample(
        type: self.stepType,
        quantity: HKQuantity(unit: .count(), doubleValue: steps),
        start: Date(),
        end: Date()
      )
      try await withCheckedThrowingContinuation { (continuation: CheckedContinuation<Void, Error>) in
        self.healthStore.save(sample) { success, error in
          if let error {
            continuation.resume(throwing: error)
          } else if !success {
            continuation.resume(throwing: ExpoHealthError.saveFailed)
          } else {
            continuation.resume()
          }
        }
      }
    }

    AsyncFunction("getDailySteps") { (days: Int) async throws -> [[String: Double]] in
      let calendar = Calendar.current
      let todayStart = calendar.startOfDay(for: Date())
      var results: [[String: Double]] = []
      for offset in 0..<days {
        let dayStart = calendar.date(byAdding: .day, value: -offset, to: todayStart)!
        let dayEnd = calendar.date(byAdding: .day, value: 1, to: dayStart)!
        let steps = try await self.sumSteps(from: dayStart, to: dayEnd)
        results.append(["startOfDayMillis": dayStart.timeIntervalSince1970 * 1000, "steps": steps])
      }
      return results
    }
  }

  private func sumSteps(from start: Date, to end: Date) async throws -> Double {
    let predicate = HKQuery.predicateForSamples(withStart: start, end: end, options: [.strictStartDate, .strictEndDate])
    return try await withCheckedThrowingContinuation { (continuation: CheckedContinuation<Double, Error>) in
      let query = HKStatisticsQuery(quantityType: stepType, quantitySamplePredicate: predicate, options: .cumulativeSum) { _, statistics, error in
        if let error {
          continuation.resume(throwing: error)
          return
        }
        let sum = statistics?.sumQuantity()?.doubleValue(for: .count()) ?? 0
        continuation.resume(returning: sum)
      }
      healthStore.execute(query)
    }
  }

  private func statusString(_ status: HKAuthorizationStatus) -> String {
    switch status {
    case .sharingAuthorized:
      return "authorized"
    case .sharingDenied:
      return "denied"
    case .notDetermined:
      fallthrough
    @unknown default:
      return "notDetermined"
    }
  }
}

enum ExpoHealthError: Error, LocalizedError {
  case unavailable
  case saveFailed

  var errorDescription: String? {
    switch self {
    case .unavailable:
      return "Health data is not available on this device."
    case .saveFailed:
      return "Failed to save health data."
    }
  }
}

