import { useFocusEffect } from '@react-navigation/native';
import { useCallback, useState } from 'react';
import { Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';

import ExpoSpeechRecognition, { type SpeechAuthorizationStatus } from '../modules/expo-speech-recognition';

const STATUS_LABELS: Record<SpeechAuthorizationStatus, string> = {
  notDetermined: 'Speech access: not requested',
  authorized: 'Speech access: granted',
  denied: 'Speech access: denied',
};

export default function TranscribeScreen() {
  const [status, setStatus] = useState<SpeechAuthorizationStatus>('notDetermined');
  const [statusMessage, setStatusMessage] = useState<string | null>(null);
  const [transcribing, setTranscribing] = useState(false);
  const [transcript, setTranscript] = useState<string | null>(null);
  const [elapsedSeconds, setElapsedSeconds] = useState<number | null>(null);

  useFocusEffect(
    useCallback(() => {
      let cancelled = false;
      (async () => {
        const current = await ExpoSpeechRecognition.getAuthorizationStatus();
        if (!cancelled) setStatus(current);
      })();
      return () => {
        cancelled = true;
      };
    }, [])
  );

  const handleRequestAccess = useCallback(async () => {
    try {
      const result = await ExpoSpeechRecognition.requestAuthorization();
      setStatusMessage(null);
      setStatus(result);
    } catch (error) {
      setStatusMessage(error instanceof Error ? error.message : String(error));
    }
  }, []);

  const handleTranscribe = useCallback(async () => {
    setStatusMessage(null);
    setTranscript(null);
    setElapsedSeconds(null);
    setTranscribing(true);

    const subscription = ExpoSpeechRecognition.addListener('onPartialTranscript', (event) => {
      setTranscript(event.text);
    });
    const startedAt = Date.now();
    try {
      const final = await ExpoSpeechRecognition.transcribeSample();
      setTranscript(final);
      setElapsedSeconds((Date.now() - startedAt) / 1000);
    } catch (error) {
      setStatusMessage(error instanceof Error ? error.message : String(error));
    } finally {
      subscription.remove();
      setTranscribing(false);
    }
  }, []);

  const canTranscribe = status === 'authorized' && !transcribing;
  const statusText = statusMessage ?? (transcribing ? 'Transcribing…' : STATUS_LABELS[status]);

  return (
    <View style={styles.container}>
      <Text style={styles.status}>{statusText}</Text>

      <View style={styles.buttons}>
        <Pressable
          style={({ pressed }) => [styles.button, pressed && styles.buttonPressed]}
          onPress={handleRequestAccess}
        >
          <Text style={styles.buttonText}>Request Access</Text>
        </Pressable>
        <Pressable
          style={[styles.button, !canTranscribe && styles.buttonDisabled]}
          disabled={!canTranscribe}
          onPress={handleTranscribe}
        >
          <Text style={[styles.buttonText, !canTranscribe && styles.buttonTextDisabled]}>Transcribe Sample</Text>
        </Pressable>
      </View>

      {transcript === null ? (
        <View style={styles.emptyState}>
          <Text style={styles.emptyStateText}>No transcript yet</Text>
        </View>
      ) : (
        <ScrollView style={styles.transcriptArea} contentContainerStyle={styles.transcriptContent}>
          <Text style={styles.transcriptText}>{transcript}</Text>
          {elapsedSeconds !== null && (
            <Text style={styles.completedText}>Completed in {elapsedSeconds.toFixed(1)} s</Text>
          )}
        </ScrollView>
      )}
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#fff',
    paddingHorizontal: 24,
    paddingTop: 24,
  },
  status: {
    fontSize: 16,
    color: '#1c1c1e',
    marginBottom: 20,
  },
  buttons: {
    gap: 12,
  },
  button: {
    backgroundColor: '#007aff',
    borderRadius: 12,
    paddingVertical: 14,
    alignItems: 'center',
  },
  buttonPressed: {
    opacity: 0.7,
  },
  buttonDisabled: {
    backgroundColor: '#e5e5ea',
  },
  buttonText: {
    color: '#fff',
    fontSize: 17,
    fontWeight: '600',
  },
  buttonTextDisabled: {
    color: '#9a9a9e',
  },
  emptyState: {
    flex: 1,
    alignItems: 'center',
    paddingVertical: 24,
  },
  emptyStateText: {
    fontSize: 15,
    color: '#8e8e93',
  },
  transcriptArea: {
    flex: 1,
    marginTop: 32,
  },
  transcriptContent: {
    paddingBottom: 24,
  },
  transcriptText: {
    fontSize: 17,
    lineHeight: 24,
    color: '#1c1c1e',
  },
  completedText: {
    fontSize: 14,
    color: '#8e8e93',
    marginTop: 16,
  },
});

